// Every pass can bundle a purchased lootbox. Keep this receipt decoder
// independent of the writer contract ABI: the lazy-pass writer uses its own
// minimal interface, while tests and injected wallets can also hand us parsed
// logs directly.
const PASS_LOOTBOX_RECEIPT_ABI = [
  'event LootBoxBuy(address indexed buyer, uint48 indexed index, uint256 amount)',
];

/** Return the bonus lootboxes minted by a confirmed pass purchase. */
export function parsePassLootboxesFromReceipt(receipt) {
  const out = [];
  if (!receipt || !Array.isArray(receipt.logs)) return out;
  for (const log of receipt.logs) {
    try {
      const parsed = log?.parsed ?? walletReceiptLog(log, new ethers.Interface(walletAbi(PASS_LOOTBOX_RECEIPT_ABI, abiGAME)));
      if (parsed?.name !== 'LootBoxBuy') continue;
      out.push({
        buyer: String(parsed.args.buyer ?? parsed.args[0]),
        lootboxIndex: boxReference(parsed.args.index ?? parsed.args[1], parsed.args.position),
        amountWei: BigInt(parsed.args.amount ?? parsed.args[2] ?? 0),
      });
    } catch (_e) { /* foreign receipt log */ }
  }
  return out;
}

/**
 * Did this pass purchase mint the buyer's free AFKing seat? A paid lazy/whale/deity
 * purchase calls GAME `_grantSeatCoin`, which mints at most once per account while the
 * free tranche lasts (token `SeatMinted`). Repeat buyers and an exhausted tranche emit none.
 * @returns {boolean}
 */
export function receiptMintedAfkingSeat(receipt) {
  const token = String(CONTRACTS.AFKING_SUB_TOKEN || '').toLowerCase();
  if (!token || !Array.isArray(receipt?.logs)) return false;
  const iface = new ethers.Interface(abiAFKING_SUB_TOKEN);
  return receipt.logs.some((log) => {
    if (String(log?.address || '').toLowerCase() !== token) return false;
    try { return iface.parseLog(log)?.name === 'SeatMinted'; } catch (_e) { return false; }
  });
}

