/** Read the NFT's actual artwork, including its configured colors / renderer.
 * Kept in an img data URL: metadata is never inserted into the page as markup.
 * Only legacy centered cards use the old circular crop. The customization
 * renderer's 104-unit viewBox retains the whole card and its badge geometry.
 */
export async function readDeityPassAppearance(symbolId) {
  if (!Number.isInteger(symbolId) || symbolId < 0 || symbolId > 31) return null;
  const cached = _deityAppearanceCache.get(symbolId);
  if (cached && cached.expiresAt > Date.now()) return cached.promise;
  const entry = { expiresAt: Date.now() + 60_000, promise: null };
  entry.promise = (async () => {
    try {
      const uri = await _deityReadContract()?.tokenURI(symbolId);
      const metadata = JSON.parse(_decodeDeityDataUri(uri, 'application/json'));
      const svg = _decodeDeityDataUri(metadata?.image, 'image/svg+xml');
      if (!svg || !/<svg\b/i.test(svg)) return null;
      return {
        src: metadata.image,
        canonicalBadge: /viewBox=["']-51\s+-51\s+102\s+102["']/.test(svg),
      };
    } catch { return null; }
  })();
  _deityAppearanceCache.set(symbolId, entry);
  const appearance = await entry.promise;
  if (!appearance && _deityAppearanceCache.get(symbolId) === entry) _deityAppearanceCache.delete(symbolId);
  return appearance;
}

/**
 * Read the authoritative deity-pass symbol catalog from the soulbound NFT.
 * Returns null rather than treating an RPC failure as 32 available symbols.
 *
 * @returns {Promise<null|{issuedCount:number,takenSymbols:Set<number>,ownersBySymbol:Map<number,string>}>}
 */
export async function readDeityPassCatalog({ fresh = false } = {}) {
  const saved = readDisplaySnapshot('deity-catalog')?.value;
  // Issued deities are permanent for this display. A complete catalog never
  // needs a read, while missing symbols remain discoverable on ordinary polls.
  if (saved?.ownersBySymbol instanceof Map && saved.ownersBySymbol.size === 32
    && [...saved.ownersBySymbol].every(([symbol, owner]) => Number.isInteger(symbol) && symbol >= 0 && symbol < 32
      && /^0x[0-9a-f]{40}$/i.test(String(owner)) && !/^0x0{40}$/i.test(String(owner)))) return saved;
  if (typeof document !== 'undefined' && document.visibilityState === 'hidden') {
    return saved ?? null;
  }
  if (_deityReadContractFactory) return _readDeityPassCatalogUncached();
  return loadDisplaySnapshot('deity-catalog', _readDeityPassCatalogUncached, { fresh, maxAge: 60_000 }).catch(() => null);
}

async function _readDeityPassCatalogUncached() {
  if (!_deityReadContractFactory) {
    // The display cache shares one read across panels. Its lifetime belongs
    // to the visible page, not whichever panel happened to request it first.
    const controller = new AbortController();
    const doc = typeof document === 'undefined' ? null : document;
    const visibility = () => { if (doc?.visibilityState === 'hidden') controller.abort(); };
    doc?.addEventListener?.('visibilitychange', visibility);
    try {
      visibility();
      controller.signal.throwIfAborted();
      const { readDeityCatalog } = await import('../chain/deity-catalog.js');
      controller.signal.throwIfAborted();
      return await readDeityCatalog({ signal: controller.signal,
        knownOwners: readDisplaySnapshot('deity-catalog')?.value?.ownersBySymbol });
    } catch (error) {
      if (controller.signal.aborted) throw controller.signal.reason;
      return null;
    } finally {
      doc?.removeEventListener?.('visibilitychange', visibility);
    }
  }
  const contract = _deityReadContract();
  if (!contract) return null;

  // One successful metadata call distinguishes a real empty catalog from a
  // dead RPC / stale address before ownerOf reverts are classified as empty.
  if (_deityReadContractFactory || !_deityContractVerified) {
    try {
      const contractName = _deityReadContractFactory
        ? await contract.name()
        : await _retryDeityRpc(() => contract.name());
      if (String(contractName || '').trim() !== 'Degenerus Deity Pass') return null;
      if (!_deityReadContractFactory) _deityContractVerified = true;
    } catch (_) {
      return null;
    }
  }

  const takenSymbols = new Set();
  const ownersBySymbol = new Map();

  // Test fakes retain ownerOf so catalog/error fixtures remain independent of RPC.
  {
    const reads = await Promise.allSettled(
      Array.from({ length: 32 }, (_, symbolId) => contract.ownerOf(symbolId)),
    );

    for (let symbolId = 0; symbolId < reads.length; symbolId += 1) {
      const result = reads[symbolId];
      if (result.status === 'fulfilled') {
        const owner = String(result.value || '').trim();
        if (!owner) return null;
        takenSymbols.add(symbolId);
        ownersBySymbol.set(symbolId, owner);
      } else if (!_isUnmintedDeityToken(result.reason)) {
        // A timeout/rate-limit must not make a claimed symbol look purchasable.
        return null;
      }
    }
  }

  return {
    issuedCount: takenSymbols.size,
    takenSymbols,
    ownersBySymbol,
  };
}

