// purchaseWhaleBundle — BUY-02 — on-chain purchaseWhalePass(buyer, quantity)
// payable. The JS export keeps the purchaseWhaleBundle name (panel call sites
// unchanged); only the contract method name moved.
// ---------------------------------------------------------------------------

/**
 * msgValueWei is the quoted total; claimable-first subtracts spendable credit
 * before setting the transaction value.
 * @param {{quantity: number | bigint, msgValueWei: bigint | string | number}} args
 * @returns {Promise<{receipt: import('ethers').TransactionReceipt}>}
 */
export async function purchaseWhaleBundle({ quantity, msgValueWei } = {}) {
  const buyer = getActingAddress();
  if (!buyer) throw new Error('Wallet not connected.');
  let qty;
  try {
    qty = BigInt(quantity);
  } catch (_e) {
    throw new Error('Quantity must be 1-1,000.');
  }
  // WHALE_MAX_QUANTITY = 1,000 paid passes (audit 4f4aa8377); 1,001 reverts InvalidQuantity.
  if (qty < 1n || qty > 1000n) throw new Error('Quantity must be 1-1,000.');
  let value = BigInt(msgValueWei ?? 0n);

  const affiliateCode = readAffiliateCode(CHAIN.id, buyer);

  // Phase 58 chokepoint — closure form mandatory.
  const receipt = await sendTx(
    async (s) => {
      let walletValue = value;
      if (readPurchaseFundingPriority() === 'claimable') {
        const reader = permissionlessReadProvider(getProvider(), { priority: 'interaction' });
        const claimable = await _buildContract(reader).claimableWinningsOf(buyer);
        walletValue = claimableFirstPayment(value, claimable).msgValueWei;
      }
      return _buildContract(s).purchaseWhalePass(await accountArg(buyer), qty, affiliateCode, { value: walletValue });
    },
    'Buy whale pass',
  );
  return { receipt };
}

